{"content":"#!/usr/bin/env node
/**
 * fix-react-conflicts.js
 *
 * Reads and validates all package.json files in the workspace, identifies
 * React peer-dependency conflicts, resolves them to compatible versions,
 * and verifies with `npm install`.
 *
 * Exit codes:
 *   0 - success (conflicts resolved, or no conflicts found)
 *   1 - failure (missing file, invalid JSON, unresolvable conflict,
 *       or post-fix `npm install` failure)
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const ROOT = __dirname;
const MANAGED_REACT_PKGS = ['react', 'react-dom'];
const MANAGED_TYPES_PKGS = ['@types/react', '@types/react-dom'];

function fail(message) {
  console.error(`ERROR: ${message}`);
  process.exit(1);
}

function discoverPackageJsonFiles() {
  const files = [path.join(ROOT, 'package.json')];
  const packagesDir = path.join(ROOT, 'packages');
  let entries = [];
  try {
    entries = fs.readdirSync(packagesDir, { withFileTypes: true });
  } catch (err) {
    fail(`packages directory is missing or unreadable: ${packagesDir} (${err.message})`);
  }
  for (const entry of entries) {
    if (entry.isDirectory()) {
      files.push(path.join(packagesDir, entry.name, 'package.json'));
    }
  }
  return files;
}

function readAndValidate(files) {
  const parsed = [];
  for (const file of files) {
    let raw;
    try {
      raw = fs.readFileSync(file, 'utf8');
    } catch (err) {
      fail(`package.json is missing or unreadable: ${file} (${err.message})`);
    }
    let data;
    try {
      data = JSON.parse(raw);
    } catch (err) {
      fail(`package.json contains invalid JSON: ${file} (${err.message})`);
    }
    if (data === null || typeof data !== 'object' || Array.isArray(data)) {
      fail(`package.json does not contain a JSON object: ${file}`);
    }
    parsed.push({ file, data });
  }
  return parsed;
}

/** Extract the leading major version number from a semver range, or null. */
function majorOf(range) {
  if (typeof range !== 'string') return null;
  const m = range.trim().match(/(\d+)\.\d+\.\d+|(\d+)\.x|(\d+)/);
  if (!m) return null;
  const major = parseInt(m[1] !== undefined ? m[1] : (m[2] !== undefined ? m[2] : m[3]), 10);
  return Number.isNaN(major) ? null : major;
}

/**
 * Conservative caret/tilde-aware intersection check for common npm ranges.
 * Returns true if the ranges can share at least one version, false if they
 * provably conflict, or null if either range is unparsable.
 */
function rangesIntersect(a, b) {
  const ma = majorOf(a);
  const mb = majorOf(b);
  if (ma === null || mb === null) return null;
  const norm = (r) => r.trim();
  const isOpen = (r) => /^(>=?|x|\*|latest)?\s*$/.test(norm(r)) || norm(r) === '*' || norm(r) === 'x';
  if (isOpen(a) || isOpen(b)) return true;
  // ^0.x.y and ~0.x.y pin tighter than the major; treat 0-major mismatches
  // on minor as conflicts too.
  if (ma === 0 || mb === 0) {
    if (ma !== mb) return false;
    const minorOf = (r) => {
      const m = norm(r).match(/(\d+)\.(\d+)/);
      return m ? parseInt(m[2], 10) : null;
    };
    const na = minorOf(a);
    const nb = minorOf(b);
    if (/^\^0\./.test(norm(a)) || /^\^0\./.test(norm(b))) {
      if (na !== null && nb !== null && na !== nb) return false;
    }
  }
  // For major >= 1, ^ and ~ ranges span within one major, so differing
  // majors mean no overlap.
  if (ma !== mb) return false;
  return true;
}

function collectReactSpecs(parsed) {
  const specs = []; // { file, pkg, range, section }
  for (const { file, data } of parsed) {
    for (const section of ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies']) {
      const deps = data[section];
      if (!deps || typeof deps !== 'object') continue;
      for (const pkg of MANAGED_REACT_PKGS) {
        if (typeof deps[pkg] === 'string') {
          specs.push({ file, pkg, range: deps[pkg], section });
        }
      }
    }
  }
  return specs;
}

function main() {
  const files = discoverPackageJsonFiles();
  // Validate everything BEFORE making any modification.
  const parsed = readAndValidate(files);
  const specs = collectReactSpecs(parsed);

  const regular = specs.filter((s) => s.section !== 'peerDependencies');
  const peers = specs.filter((s) => s.section === 'peerDependencies');

  // 1. Regular (non-peer) React specs must mutually intersect per package-name.
  //    Otherwise no single installed version can satisfy them: unresolvable.
  for (const pkg of MANAGED_REACT_PKGS) {
    const regs = regular.filter((s) => s.pkg === pkg);
    for (let i = 0; i < regs.length; i++) {
      for (let j = i + 1; j < regs.length; j++) {
        const inter = rangesIntersect(regs[i].range, regs[j].range);
        if (inter === false) {
          fail(
            `Unresolvable conflict for "${pkg}": ` +
            `"${regs[i].range}" in ${regs[i].file} (${regs[i].section}) ` +
            `does not overlap "${regs[j].range}" in ${regs[j].file} (${regs[j].section}). ` +
            `No changes were made.`
          );
        }
        if (inter === null) {
          fail(
            `Unresolvable conflict for "${pkg}": unable to parse version ranges ` +
            `"${regs[i].range}" (${regs[i].file}) and "${regs[j].range}" (${regs[j].file}). ` +
            `No changes were made.`
          );
        }
      }
    }
  }

  // 2. Peer specs must intersect the regular specs for the same package.
  const conflicts = [];
  for (const peer of peers) {
    const regs = regular.filter((s) => s.pkg === peer.pkg);
    for (const reg of regs) {
      const inter = rangesIntersect(peer.range, reg.range);
      if (inter === false) {
        conflicts.push({ peer, reg });
      } else if (inter === null) {
        fail(
          `Unresolvable conflict for "${peer.pkg}": unable to parse peer range ` +
          `"${peer.range}" (${peer.file}) against "${reg.range}" (${reg.file}). ` +
          `No changes were made.`
        );
      }
    }
  }

  if (conflicts.length === 0) {
    console.log('No React peer dependency conflicts found. No changes needed.');
    process.exit(0);
  }

  // 3. Resolve: align every React spec to the majority major used by regular
  //    dependencies (ties broken by highest major). Peer-only packages follow.
  const targetMajor = {};
  for (const pkg of MANAGED_REACT_PKGS) {
    const regs = regular.filter((s) => s.pkg === pkg);
    const peerOnly = regs.length === 0;
    const pool = peerOnly ? specs.filter((s) => s.pkg === pkg) : regs;
    const counts = new Map();
    for (const s of pool) {
      const mj = majorOf(s.range);
      if (mj === null) {
        fail(
          `Unresolvable conflict for "${pkg}": unable to parse range ` +
          `"${s.range}" in ${s.file}. No changes were made.`
        );
      }
      counts.set(mj, (counts.get(mj) || 0) + 1);
    }
    let best = null;
    for (const [mj, n] of counts) {
      if (best === null || n > counts.get(best) || (n === counts.get(best) && mj > best)) {
        best = mj;
      }
    }
    targetMajor[pkg] = best;
  }

  // Pick concrete replacement ranges from the winning major's existing specs
  // so style (^/~) stays consistent with the workspace.
  const replacement = {};
  for (const pkg of MANAGED_REACT_PKGS) {
    const cands = regular.filter((s) => s.pkg === pkg && majorOf(s.range) === targetMajor[pkg]);
    const pool = cands.length > 0 ? cands : specs.filter((s) => s.pkg === pkg && majorOf(s.range) === targetMajor[pkg]);
    // Prefer the highest minimum version among candidates.
    const withFloor = pool.map((s) => {
      const m = s.range.trim().match(/(\d+)\.(\d+)\.(\d+)/);
      return { s, floor: m ? [ +m[1], +m[2], +m[3] ] : [targetMajor[pkg], 0, 0] };
    }).sort((a, b) =>
      b.floor[0] - a.floor[0] || b.floor[1] - a.floor[1] || b.floor[2] - a.floor[2]);
    replacement[pkg] = withFloor.length > 0 ? withFloor[0].s.range : `^${targetMajor[pkg]}.0.0`;
  }

  // Safety: every regular spec must intersect the chosen replacement.
  for (const pkg of MANAGED_REACT_PKGS) {
    for (const reg of regular.filter((s) => s.pkg === pkg)) {
      if (rangesIntersect(reg.range, replacement[pkg]) === false) {
        fail(
          `Unresolvable conflict for "${pkg}": cannot align "${reg.range}" ` +
          `(${reg.file}) with target "${replacement[pkg]}". No changes were made.`
        );
      }
    }
  }

  // 4. Apply changes (only now that resolution is proven possible).
  let updatedFiles = 0;
  for (const { file, data } of parsed) {
    let changed = false;
    for (const section of ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies']) {
      const deps = data[section];
      if (!deps || typeof deps !== 'object') continue;
      for (const pkg of MANAGED_REACT_PKGS) {
        if (typeof deps[pkg] === 'string' && majorOf(deps[pkg]) !== targetMajor[pkg]) {
          console.log(`${file}: ${section}.${pkg} "${deps[pkg]}" -> "${replacement[pkg]}"`);
          deps[pkg] = replacement[pkg];
          changed = true;
        }
      }
      // Keep @types/react* in step with the React major in devDependencies.
      if (section === 'devDependencies') {
        for (const typesPkg of MANAGED_TYPES_PKGS) {
          if (typeof deps[typesPkg] === 'string' && majorOf(deps[typesPkg]) !== targetMajor['react']) {
            const next = `^${targetMajor['react']}.0.0`;
            console.log(`${file}: ${section}.${typesPkg} "${deps[typesPkg]}" -> "${next}"`);
            deps[typesPkg] = next;
            changed = true;
          }
        }
      }
    }
    if (changed) {
      try {
        fs.writeFileSync(file, JSON.stringify(data, null, 2) + '\n', 'utf8');
        updatedFiles++;
      } catch (err) {
        fail(`Failed to write ${file} (${err.message})`);
      }
    }
  }

  if (updatedFiles === 0) {
    console.log('No React peer dependency conflicts found. No changes needed.');
    process.exit(0);
  }

  // 5. Verify with npm install.
  console.log('Verifying with `npm install`...');
  try {
    execSync('npm install', { cwd: ROOT, stdio: 'inherit' });
  } catch (err) {
    fail('`npm install` failed after applying React version fixes.');
  }

  console.log(`All package.json files updated with compatible React versions (${updatedFiles} file(s) changed). npm install completed without errors.`);
  process.exit(0);
}

main();
